// 品牌图标内联 XML — 供 BrandIcon (react-native-svg SvgXml) 使用
// 平台 SVG 来源于 src/assets/icons/platform/*.svg（处理：去 width/height/注释/clip-path 包裹）
// 媒体库 SVG 来源于 dashboard-icons (CC0-1.0) / simple-icons (CC0-1.0) / 手绘 fallback

function stripSvg(raw: string): string {
  let s = raw.replace(/\s+width="[^"]*"/g, '').replace(/\s+height="[^"]*"/g, '');
  s = s.replace(/<!--.*?-->/gs, '');
  s = s.replace(/<defs>[\s\S]*?<\/defs>/g, '');
  s = s.replace(/<g[^>]*clip-path="[^"]*"[^>]*>([\s\S]*?)<\/g>/g, '$1');
  s = s.replace(/\s{2,}/g, ' ').trim();
  if (!s.includes('xmlns')) {
    s = s.replace('<svg ', '<svg xmlns="http://www.w3.org/2000/svg" ');
  }
  return s;
}

